import Foundation

#if canImport(Darwin)
private final class BundleFinder {}
#endif

extension Bundle {
    /// Known resource bundle names generated by SwiftPM (`<Package>_<Target>.bundle` on Apple
    /// platforms, `<Package>_<Target>.resources` on Linux/Windows) and Xcode.
    internal static let vieLotusCoreBundleNames = [
        "VietLotusIM_VieLotusCore.bundle",
        "VieLotusCore_VieLotusCore.bundle",
        "VietLotusIM_VieLotusCore.resources",
        "VieLotusCore_VieLotusCore.resources",
    ]

    /// Safe, crash-free resource bundle resolver for `VieLotusCore`.
    ///
    /// Why not `Bundle.module`?
    /// SwiftPM's synthesized `Bundle.module` accessor for command-line/executable products only
    /// checks two paths:
    /// 1. `Bundle.main.bundleURL/VietLotusIM_VieLotusCore.bundle` (the `.app` root, which macOS
    ///    `codesign --strict` forbids because unsealed files are not allowed at the `.app` root).
    /// 2. The hardcoded absolute path of the CI build machine (e.g. `/Users/runner/work/...`).
    ///
    /// When `VieLotusIM.app` is installed to `/Library/Input Methods/VieLotusIM.app` on an
    /// end-user machine with the resource bundle properly placed inside `Contents/Resources/`,
    /// SwiftPM's `Bundle.module` fails both checks and triggers `fatalError` (`EXC_BREAKPOINT`).
    ///
    /// `Bundle.vieLotusCore` checks `Bundle.main.resourceURL` (`Contents/Resources/`) first,
    /// then framework/XCTest/CLI/Linux/Windows locations and source-tree fallbacks, and never
    /// calls `fatalError`.
    public static let vieLotusCore: Bundle = {
        var candidates: [URL?] = []

        if let override = ProcessInfo.processInfo.environment["PACKAGE_RESOURCE_BUNDLE_PATH"]
            ?? ProcessInfo.processInfo.environment["PACKAGE_RESOURCE_BUNDLE_URL"] {
            candidates.append(URL(fileURLWithPath: override))
        }

        candidates.append(contentsOf: [
            // 1. Standard signed macOS .app bundle location: Contents/Resources/
            Bundle.main.resourceURL,
            Bundle.main.bundleURL.appendingPathComponent("Contents/Resources", isDirectory: true),
            // 2. CLI / SwiftPM executable directory (e.g. .build/release/)
            Bundle.main.bundleURL,
            Bundle.main.executableURL?.deletingLastPathComponent(),
        ])

        var fallbackBundles: [Bundle] = [Bundle.main]

        #if canImport(Darwin)
        let finderBundle = Bundle(for: BundleFinder.self)
        candidates.append(contentsOf: [
            finderBundle.resourceURL,
            finderBundle.bundleURL,
            finderBundle.bundleURL.deletingLastPathComponent(),
        ])
        fallbackBundles.append(finderBundle)
        #elseif os(Linux)
        candidates.append(contentsOf: [
            URL(fileURLWithPath: "/usr/share/vielotus", isDirectory: true),
            URL(fileURLWithPath: "/usr/local/share/vielotus", isDirectory: true),
        ])
        #elseif os(Windows)
        if let programFiles = ProcessInfo.processInfo.environment["ProgramFiles"] {
            candidates.append(
                URL(fileURLWithPath: programFiles, isDirectory: true)
                    .appendingPathComponent("VieLotusIM", isDirectory: true)
            )
        }
        #endif

        #if DEBUG && !VIELOTUS_OPEN_CORE_MACOS
        let sourceResourcesDir: URL? = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Resources", isDirectory: true)
        #else
        let sourceResourcesDir: URL? = nil
        #endif

        return resolveVieLotusCore(
            in: candidates,
            fallbackBundles: fallbackBundles,
            sourceResourcesURL: sourceResourcesDir
        )
    }()

    /// Resolves the `VieLotusCore` resource bundle from an ordered list of candidate directories
    /// without ever invoking `fatalError`. Internal for deterministic unit testing of relocated
    /// `.app` bundle layouts.
    internal static func resolveVieLotusCore(
        in candidates: [URL?],
        fallbackBundles: [Bundle] = [],
        sourceResourcesURL: URL? = nil
    ) -> Bundle {
        let fm = FileManager.default

        for candidate in candidates {
            guard let dir = candidate else { continue }
            // Direct override pointing straight to the .bundle or .resources directory
            if dir.pathExtension == "bundle" || dir.pathExtension == "resources",
               fm.fileExists(atPath: dir.path),
               let bundle = Bundle(url: dir) {
                return bundle
            }
            for bundleName in vieLotusCoreBundleNames {
                let bundleURL = dir.appendingPathComponent(bundleName, isDirectory: true)
                if fm.fileExists(atPath: bundleURL.path),
                   let bundle = Bundle(url: bundleURL) {
                    return bundle
                }
            }
        }

        // Flat resource layout (e.g. resources copied directly into Contents/Resources/ or iOS app bundle)
        for fallback in fallbackBundles {
            #if !VIELOTUS_OPEN_CORE_MACOS
            if fallback.url(forResource: "TuDienTuGhep", withExtension: "json") != nil
                || fallback.url(forResource: "TuDienTuGhep", withExtension: "txt") != nil {
                return fallback
            }
            #endif
            if fallback.url(forResource: "typing-modes", withExtension: "yml") != nil {
                return fallback
            }
        }

        // Development / source-tree fallback
        if let sourceResourcesURL,
           fm.fileExists(atPath: sourceResourcesURL.path),
           let bundle = Bundle(url: sourceResourcesURL) {
            return bundle
        }

        return fallbackBundles.first ?? Bundle.main
    }

    #if !SWIFT_PACKAGE
    /// Compatibility fallback for `Bundle.module` when compiling as an Xcode target / framework.
    static var module: Bundle {
        vieLotusCore
    }
    #endif
}
